const toTime = DateTime.fromFormat(base.horario_agendado, 'HH:mm')
  .plus({ minutes: dur })
  .toFormat('HH:mm');

return {
  json: {
    ...base,
    id_paciente_final: base.patient_id_remarcar,  // já vem do Validar Slot Remarcar
    data_agendada_iso: dataISO,
    toTime_calculado:  toTime
  }
};

